const tabId = 343605502;
const jobs = await browserjs(tabId, () => {
  // Let's find all job listings on the page
  // CalCareers usually puts job items in cards or divs or list
  const results = [];
  // Let's find elements with job control or links
  const jobCards = document.querySelectorAll('.card, .job-item, .search-result, [class*="job"], tr');

  // Or parse by finding all job titles / job controls
  const titles = Array.from(document.querySelectorAll('a')).filter(a => /\(\d{6}\)/.test(a.textContent) && !a.textContent.includes('View '));

  return titles.map(t => {
    // Traverse parent or siblings to get full details
    let parent = t.closest('.card') || t.parentElement;
    while (parent && !parent.innerText.includes('Job Control:') && parent.parentElement) {
      parent = parent.parentElement;
    }
    // If we have a container with the details:
    const text = parent ? parent.innerText : '';
    return {
      title: t.textContent.trim(),
      href: t.href,
      fullText: text
    };
  });
});

console.log("Found jobs count:", jobs.length);
console.log("Jobs details:", JSON.stringify(jobs, null, 2));

const tabId = 343605502;
const resultDOM = await browserjs(tabId, () => {
  // Find where the jobs are located
  // Look for elements containing "Job Control:"
  const allElements = Array.from(document.querySelectorAll('*'));
  const jobControlSpans = allElements.filter(el => el.children.length === 0 && el.textContent.trim() === 'Job Control:');

  return jobControlSpans.map(jc => {
    // Find enclosing block/container
    let curr = jc;
    for (let i = 0; i < 6; i++) {
      if (curr.parentElement) curr = curr.parentElement;
      if (curr.classList.contains('row') || curr.tagName === 'LI' || curr.tagName === 'TR' || curr.classList.contains('col-xs-12') || curr.id.includes('Job')) {
        break;
      }
    }
    return {
      containerTag: curr.tagName,
      containerClass: curr.className,
      containerId: curr.id,
      text: curr.innerText
    };
  });
});

console.log("Job results extracted:", JSON.stringify(resultDOM, null, 2));

const tabId = 343605502;
const detailedJobs = await browserjs(tabId, () => {
  const allElements = Array.from(document.querySelectorAll('*'));
  const jobControlSpans = allElements.filter(el => el.children.length === 0 && el.textContent.trim() === 'Job Control:');

  return jobControlSpans.map(jc => {
    // Find the enclosing job listing card/container
    // Go up until we find the container that holds the job title link and all details
    let curr = jc;
    while (curr && !curr.querySelector('a[href*="JobPosting.aspx"]') && curr.parentElement) {
      curr = curr.parentElement;
    }
    // Now curr or curr.parentElement contains the whole card
    const card = curr.closest('.col-xs-12') || curr.parentElement;
    return {
      text: card.innerText,
      jobPostingLink: card.querySelector('a[href*="JobPosting.aspx"]')?.href
    };
  });
});

console.log("Detailed jobs count:", detailedJobs.length);
detailedJobs.forEach((job, idx) => {
  console.log(`\n--- JOB #${idx + 1} ---`);
  console.log(job.text);
  console.log("Link:", job.jobPostingLink);
});

