const jobs = await browserjs(tabId, () => {
  // Let's find all job listings on the page
  // CalCareers usually puts job items in cards or divs or list
  const results = [];
  // Let's find elements with job control or links
  const jobCards = document.querySelectorAll('.card, .job-item, .search-result, [class*="job"], tr');

  // Or parse by finding all job titles / job controls
  const titles = Array.from(document.querySelectorAll('a')).filter(a => /\(\d{6}\)/.test(a.textContent) && !a.textContent.includes('View '));

  return titles.map(t => {
    // Traverse parent or siblings to get full details
    let parent = t.closest('.card') || t.parentElement;
    while (parent && !parent.innerText.includes('Job Control:') && parent.parentElement) {
      parent = parent.parentElement;
    }
    // If we have a container with the details:
    const text = parent ? parent.innerText : '';
    return {
      title: t.textContent.trim(),
      href: t.href,
      fullText: text
    };
  });
});

console.log("Found jobs count:", jobs.length);
